import java.io.InputStream;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        if (n == 0) return;

        int[] head = new int[n + 1];
        int[] to = new int[2 * (n - 1) + 1];
        int[] next = new int[2 * (n - 1) + 1];
        int edgeCount = 0;

        for (int i = 0; i < n - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            edgeCount++;
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount;

            edgeCount++;
            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount;
        }

        int[] order = new int[n];
        int[] parent = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        int headQueue = 0;
        int tailQueue = 0;

        order[tailQueue++] = 1;
        visited[1] = true;

        while (headQueue < tailQueue) {
            int u = order[headQueue++];
            for (int e = head[u]; e != 0; e = next[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    order[tailQueue++] = v;
                }
            }
        }

        int[] size = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            size[i] = 1;
        }

        int minDiff = n;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            if (u != 1) {
                int p = parent[u];
                size[p] += size[u];
                int diff = Math.abs(2 * size[u] - n);
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        System.out.println(minDiff);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[32768];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() {
            if (head >= tail) {
                head = 0;
                try {
                    tail = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    tail = -1;
                }
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return 0;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + c - '0';
                }
                c = read();
            }
            return res;
        }
    }
}
