const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;

    const head = new Int32Array(n + 1).fill(-1);
    const to = new Int32Array(2 * n);
    const next = new Int32Array(2 * n);
    let edgeCount = 0;

    function addEdge(u, v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    for (let i = 0; i < n - 1; i++) {
        const u = readInt();
        const v = readInt();
        addEdge(u, v);
        addEdge(v, u);
    }

    const order = new Int32Array(n);
    const parent = new Int32Array(n + 1);
    let headQueue = 0;
    let tailQueue = 0;

    order[tailQueue++] = 1;
    parent[1] = 0;

    while (headQueue < tailQueue) {
        const u = order[headQueue++];
        for (let e = head[u]; e !== -1; e = next[e]) {
            const v = to[e];
            if (v !== parent[u]) {
                parent[v] = u;
                order[tailQueue++] = v;
            }
        }
    }

    const sz = new Int32Array(n + 1).fill(1);
    let minDiff = n;

    for (let i = n - 1; i > 0; i--) {
        const u = order[i];
        const p = parent[u];
        sz[p] += sz[u];

        const diff = Math.abs(n - 2 * sz[u]);
        if (diff < minDiff) {
            minDiff = diff;
        }
    }

    console.log(minDiff);
}

main();
